42:     const notificaciones: any = await new Promise((resolve, reject) => {
43:       this.post('/notificacion', notificacion).subscribe(
44:         response=>{
45:         },
46:         error=>{
47:         }
48:       );
49:     });
50: 
51:     this.connectWebSocket();
52: 
