76:   private async obteneMensaje(estado: string,endpoint:string) {
77:     switch (estado) {
78:       case 'PRO':
79:         this.mensaje = 'Contratación te asignó una de cumplido proveedor';
80:         this.asunto = 'Asignacion de Cumplido';
81:         await this.obtenerDestinatario(endpoint);
82:         this.destinatarios.push(this.documentoResponsable)
83:         break;
84:       case 'PRC':
85:         this.mensaje = 'El supervisor te asignó una de cumplido proveedor';
86:         this.asunto = 'Asignacion de Cumplido';
87:         break;
88:       case 'AO':
89:         this.mensaje =
90:           'El ordenador ha aprobado una solicitud de cumplido proveedor';
91:         this.asunto = 'Aprobacion de Cumplido';
92:         await this.obtenerDestinatario(endpoint);
93:         this.destinatarios.push(this.documentoResponsable)
94:         break;
95:       case 'RO':
96:         this.mensaje =
97:           'El Ordenador rechazo  la solicitud de  cumplido proveedor';
98:         this.asunto = 'Rechazo de Cumplido';
99:         break;
100:       case 'RC':
101:         this.mensaje =
102:           'Contratación ha rechazado la solicitud de cumplido proveedor';
103:           this.asunto = 'Rechazo de Cumplido';
104:           await this.obtenerDestinatario(endpoint);
105:          this.destinatarios.push(this.documentoResponsable)
106:          
107:         break;
108:         case 'AC':
109:           this.mensaje =
110:             'Contratación ha rechazado la solicitud de cumplido proveedor';
111:             this.asunto = 'Rechazo de Cumplido';
112:             await this.obtenerDestinatario(endpoint);
113:            this.destinatarios.push(this.documentoResponsable)
114:            
115:           break;
116:       default:
117:         this.mensaje = '';
118:         break;
119:     }
120:   }
